mkitem!{mkstruct!{#[doc = " Representation of `F` that has handled subnormals."] #[derive (Clone , Copy , Debug)] struct Norm < F : Float > { #[doc = " Normalized significand with one guard bit, unsigned."] m : F :: Int , #[doc = " Exponent of the mantissa such that `m * 2^e = x`. Accounts for the shift in the mantissa"] #[doc = " and the guard bit; that is, 1.0 will normalize as `m = 1 << 53` and `e = -53`."] e : i32 , neg : bool , }}}
mkitem!{mkimpl!{impl < F : Float > Norm < F > { #[doc = " Unbias the exponent and account for the mantissa's precision, including the guard bit."] const EXP_UNBIAS : u32 = F :: EXP_BIAS + F :: SIG_BITS + 1 ; #[doc = " Values greater than this had a saturated exponent (infinity or NaN), OR were zero and we"] #[doc = " adjusted the exponent such that it exceeds this threashold."] const ZERO_INF_NAN : u32 = F :: EXP_SAT - Self :: EXP_UNBIAS ; fn from_float (x : F) -> Self { let mut ix = x . to_bits () ; let mut e = x . ex () as i32 ; let neg = x . is_sign_negative () ; if e == 0 { let scale_i = F :: BITS - 1 ; let scale_f = F :: from_parts (false , scale_i + F :: EXP_BIAS , F :: Int :: ZERO) ; let scaled = x * scale_f ; ix = scaled . to_bits () ; e = scaled . ex () as i32 ; e = if e == 0 { 1 << F :: EXP_BITS } else { e - scale_i as i32 } ; } e -= Self :: EXP_UNBIAS as i32 ; ix &= F :: SIG_MASK ; ix |= F :: IMPLICIT_BIT ; ix <<= 1 ; Self { m : ix , e , neg } } #[doc = " True if the value was zero, infinity, or NaN."] fn is_zero_nan_inf (self) -> bool { self . e >= Self :: ZERO_INF_NAN as i32 } #[doc = " The only value we have"] fn is_zero (self) -> bool { self . e > Self :: ZERO_INF_NAN as i32 } }}}